def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    count = len(values)
    try:
        average = sum(values) / count
    except ZeroDivisionError:
        return None
    return {
        "value": average,
        "trace": {
            "values": values,
            "count": count,
            "average": average,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
